cpp Copy class Connection { void disconnect (); bool isConnected () const ; explicit operator bool () const ; // destructor does NOT auto-disconnect }; class Connection {
    void disconnect();
    bool isConnected() const;
    explicit operator bool() const;   // destructor does NOT auto-disconnect
};  Disconnected by the receiver's ConnectionGroup on destruction; Connection 's own destructor does not . disconnect() logically invalidates pending UIThread / NewThread tasks, but does not interrupt a slot already running .  Pitfall Connection is not an RAII guard ; a temporary handle's destructor does not disconnect. Call disconnect() explicitly or rely on the receiver's group. it is safe to ignore the return of connect ; calling disconnect after the signal is destroyed is safe ( alive is atomic).  Version : passive-handle semantics since v1.8.1 ; the alive flag became atomic and pending tasks are cancelled since v1.24.0 .

cpp Copy class ConnectionGroup : public std :: enable_shared_from_this < ConnectionGroup > { void disconnectAll (); size_t size () const ; }; class ConnectionGroup : public std::enable_shared_from_this<ConnectionGroup> {
    void disconnectAll(); size_t size() const;
};  Used internally by UIElement / Window to disconnect all connections they own. size() counts only live connections; manually disconnected connections are not counted.  Pitfall disconnectAll() only removes connections; it does not invoke user slots.

cpp Copy template < typename ... TArgs > class ZSignal { using SlotType = std :: function < void ( TArgs ...) > ; Connection connect ( SlotType slot , ConnectionThread thread = ConnectionThread :: CurrentThread , std :: shared_ptr < ConnectionGroup > group = nullptr ); template < class Receiver , class Slot > Connection connect ( Receiver * receiver , Slot && slot , ConnectionThread thread = ConnectionThread :: CurrentThread ); void Fire ( TArgs ... targs ) const ; void operator ()( TArgs ... targs ) const ; }; template<typename... TArgs> class ZSignal {
    using SlotType = std::function<void(TArgs...)>;
    Connection connect(SlotType slot,
                       ConnectionThread thread = ConnectionThread::CurrentThread,
                       std::shared_ptr<ConnectionGroup> group = nullptr);
    template<class Receiver, class Slot>
    Connection connect(Receiver* receiver, Slot&& slot,
                       ConnectionThread thread = ConnectionThread::CurrentThread);
    void Fire(TArgs... targs) const;
    void operator()(TArgs... targs) const;
};  Fire with Fire ( there is no emit macro ). ZSignal is not copyable or movable ; it is a member of controls/windows — never put it in a movable container. Signal arguments are passed to slots as lvalues ; do not declare T&& slot parameters, and prefer const T& for large objects.  Pitfall Fire iterates a snapshot , so a slot may safely disconnect ; re-firing the same signal inside a slot goes through the "reentrant" path (local copy) — avoid deep recursion there. Fire concurrent with ZSignal destruction is UB; fire and destroy a signal on the same thread. an exception thrown by a slot propagates out of Fire ; later slots do not run. Avoid throwing from signal slots.  Version : v1.18.0 adds a RAII guard so a throwing slot still restores reentrancy depth and releases the snapshot; non-movable since v1.24.0 .

elem->Connect(sig, slot) , Connect(elem, sig, slot) and sig.connect(elem, slot) register the connection on elem 's ConnectionGroup and disconnect when elem is destroyed; Window supports the same. ConnectWeak(self, sig, slot) holds a weak reference; the slot's first parameter is T* or T& , keeps self alive during execution, and does nothing if the object is gone. Member-function pointers go through the free Connect / ConnectWeak only (compile-time type check); elem->Connect(sig, &Class::Method) is no longer supported.  cpp Copy auto panel = std :: make_shared < Panel > (); panel -> Connect ( btn -> Clicked , [ this ] { Refresh (); }); Connect ( panel , btn -> Clicked , & Panel :: OnClick ); btn -> Clicked . connect ( panel , [ this ] { Refresh (); }); ConnectWeak ( panel , btn -> Clicked , []( Panel * self ) { self -> Refresh (); }); ConnectWeak ( panel , btn -> Clicked , & Panel :: OnClick ); auto panel = std::make_shared<Panel>();

panel->Connect(btn->Clicked, [this] { Refresh(); });
Connect(panel, btn->Clicked, &Panel::OnClick);
btn->Clicked.connect(panel, [this] { Refresh(); });

ConnectWeak(panel, btn->Clicked, [](Panel* self) { self->Refresh(); });
ConnectWeak(panel, btn->Clicked, &Panel::OnClick);  Note Menu / MenuItem / Timer still use signal.connect and do not auto-disconnect.  Pitfall do not capture self 's shared_ptr by value inside a ConnectWeak slot — that creates a signal → slot → self → signal strong cycle.

cpp Copy namespace UIZSignals { inline ZSignal < Window * , ID2D1RenderTarget *> DrawOverlay ; inline ZSignal < Window * , float , float > GlobalMouseDown ; inline ZSignal < Window *> WindowActivated , WindowDeactivated ; inline ZSignal < Window * , UIElement *> ElementCaptureRequest , ElementCaptureRelease , RepaintRequest ; inline ZSignal < Window *> LayoutInvalidated ; inline ZSignal <> DeviceReset , ReloadAcrylic ; inline ZSignal < const std :: wstring &> Error ; // v1.16.0 } namespace UIZSignals {
    inline ZSignal<Window*, ID2D1RenderTarget*> DrawOverlay;
    inline ZSignal<Window*, float, float> GlobalMouseDown;
    inline ZSignal<Window*> WindowActivated, WindowDeactivated;
    inline ZSignal<Window*, UIElement*> ElementCaptureRequest, ElementCaptureRelease, RepaintRequest;
    inline ZSignal<Window*> LayoutInvalidated;
    inline ZSignal<> DeviceReset, ReloadAcrylic;
    inline ZSignal<const std::wstring&> Error;         // v1.16.0
}  RepaintRequest / LayoutInvalidated /capture signals only fall back for unmounted elements; mounted ones route directly via Window . DeviceReset : release all caches keyed to the render target/device (e.g. ImageDeviceCache ).  Pitfall DrawOverlay carries a Window* ; subscribers must filter by GetWindow() , or window A's overlay draws onto window B (classic multi-window cross-talk).

