ea DIP // ---- Expander: collapsible card ---- class Expander : public UIElement { Expander ( const std :: wstring & title = L "" , const std :: wstring & subtitle = L "" ); void SetTitle / SetSubtitle ( const std :: wstring & ); void SetContent ( std :: shared_ptr < UIElement > ); std :: shared_ptr < UIElement > GetContent () const ; void SetExpanded ( bool ); bool IsExpanded () const ; void Toggle (); void SetIcon ( Icon , float size = 22.0f ); // leading icon (None = none) ZSignal < bool > ExpandedChanged ; }; // ---- SettingsList: settings row list ---- class SettingsList : public UIElement { void AddRow ( Icon , const std :: wstring & text , const std :: wstring & subtitle , std :: function < void () > onClick , const std :: wstring & id = {}); ZSignal < int > RowClicked ; }; // ---- drag & drop: payload / events ----
